cd /workspace && cat > /tmp/dbg.cpp <<'EOF'
#include "fib.hpp"
#include <cstdio>
int main(){
    PrefixTable t;
    t.put(0x20010db800000001ULL, 1ULL, 128, 3);
    printf("size=%zu\n", t.size());
    ip6_t ip{0x20010db800000001ULL, 1ULL};
    uint32_t hop=0;
    bool found = t.lookup(ip, hop);
    printf("found=%d hop=%u\n", (int)found, hop);
    FibKey k{0x20010db800000001ULL,1ULL,128};
    auto it = t.entries().find(k);
    printf("direct find=%d\n", (int)(it!=t.entries().end()));
    return 0;
}
EOF
g++ -std=c++14 -O0 -I src /tmp/dbg.cpp src/fib.cpp -o /tmp/dbg && /tmp/dbg
